import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';

export const REASON_CODES = [
  'requested_ready',
  'reminder_due',
  'nudge_allowed',
  'already_delivered',
  'new_user_grace',
  'quiet_hours',
  'daily_cap_reached',
  'unsupported_origin',
];

const NEW_USER_GRACE_MS = 48 * 60 * 60 * 1000; // no inferred nudges for 48h
const QUIET_START_HOUR = 21; // local time, inclusive
const QUIET_END_HOUR = 9; // local time, exclusive
const LOCK_STALE_MS = 10_000;
const LOCK_TIMEOUT_MS = 30_000;

function stateDir() {
  return process.env.STATE_DIR || path.join(process.cwd(), '.state');
}

function userFile(dir, userId) {
  const h = crypto.createHash('sha256').update(String(userId)).digest('hex');
  return path.join(dir, `user-${h}.json`);
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function withLock(lockPath, fn) {
  const start = Date.now();
  for (;;) {
    try {
      await fs.mkdir(lockPath);
      break;
    } catch (e) {
      if (e.code !== 'EEXIST') throw e;
      try {
        const st = await fs.stat(lockPath);
        if (Date.now() - st.mtimeMs > LOCK_STALE_MS) {
          await fs.rmdir(lockPath).catch(() => {});
          continue;
        }
      } catch {}
      if (Date.now() - start > LOCK_TIMEOUT_MS) throw new Error('lock timeout');
      await sleep(5 + Math.random() * 20);
    }
  }
  try {
    return await fn();
  } finally {
    await fs.rmdir(lockPath).catch(() => {});
  }
}

function localParts(date, timezone) {
  let tz = timezone;
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: tz });
  } catch {
    tz = 'UTC';
  }
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);
  const get = (t) => parts.find((p) => p.type === t).value;
  return { day: `${get('year')}-${get('month')}-${get('day')}`, hour: Number(get('hour')) };
}

async function readState(file) {
  try {
    return JSON.parse(await fs.readFile(file, 'utf8'));
  } catch (e) {
    if (e.code === 'ENOENT') return { delivered: {}, nudges: {} };
    throw e;
  }
}

async function writeState(file, state) {
  const tmp = `${file}.${process.pid}.${crypto.randomBytes(4).toString('hex')}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(state));
  await fs.rename(tmp, file);
}

export async function decide({ user, candidate, now, config }) {
  const origin = candidate?.origin;
  if (origin !== 'requested' && origin !== 'inferred' && origin !== 'reminder') {
    return { send: false, reasonCode: 'unsupported_origin' };
  }

  const dir = stateDir();
  await fs.mkdir(dir, { recursive: true });
  const file = userFile(dir, user.id);

  return withLock(`${file}.lock`, async () => {
    const state = await readState(file);
    state.delivered ??= {};
    state.nudges ??= {};
    const key = String(candidate.id);

    if (state.delivered[key]) return { send: false, reasonCode: 'already_delivered' };

    const deliver = async (reasonCode, nudgeDay) => {
      state.delivered[key] = now.toISOString();
      if (nudgeDay) state.nudges[nudgeDay] = (state.nudges[nudgeDay] || 0) + 1;
      await writeState(file, state);
      return { send: true, reasonCode };
    };

    // The user asked for these: always delivered (once), never counted as nudges.
    if (origin === 'requested') return deliver('requested_ready');
    if (origin === 'reminder') return deliver('reminder_due');

    // Inferred suggestions: the assistant's own guess, so be conservative.
    const created = Math.max(Date.parse(user.createdAt), Date.parse(user.profileCreatedAt));
    if (!Number.isFinite(created) || now.getTime() - created < NEW_USER_GRACE_MS) {
      return { send: false, reasonCode: 'new_user_grace' };
    }

    const { day, hour } = localParts(now, user.timezone);
    if (hour >= QUIET_START_HOUR || hour < QUIET_END_HOUR) {
      return { send: false, reasonCode: 'quiet_hours' };
    }

    const cap = Number(config?.dailyNudgeCap);
    const limit = Number.isFinite(cap) && cap > 0 ? Math.floor(cap) : 0;
    if ((state.nudges[day] || 0) >= limit) {
      return { send: false, reasonCode: 'daily_cap_reached' };
    }

    return deliver('nudge_allowed', day);
  });
}

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fork } from 'node:child_process';
import assert from 'node:assert/strict';

const botPath = process.argv[2];
if (process.argv[3] === 'child') {
  const { decide } = await import(botPath);
  const user = { id: 'u1', timezone: 'UTC', createdAt: '2026-01-01T00:00:00Z', profileCreatedAt: '2026-01-01T00:00:00Z' };
  const r = [];
  for (let i = 0; i < 5; i++)
    r.push(await decide({ user, candidate: { id: `${process.pid}-${i}`, origin: 'inferred' }, now: new Date('2026-10-23T12:00:00Z'), config: { dailyNudgeCap: 3 } }));
  process.send(r.filter((x) => x.send).length);
  process.exit(0);
}

process.env.STATE_DIR = fs.mkdtempSync(path.join(os.tmpdir(), 'st-'));
const { decide, REASON_CODES } = await import(botPath);
const old = { id: 'a', timezone: 'Europe/Istanbul', createdAt: '2026-01-01T00:00:00Z', profileCreatedAt: '2026-01-02T00:00:00Z' };
const nu = { id: 'b', timezone: 'UTC', createdAt: '2026-10-23T10:00:00Z', profileCreatedAt: '2026-10-23T10:05:00Z' };
const cfg = { dailyNudgeCap: 2 };
const noon = new Date('2026-10-23T09:00:00Z'); // 12:00 Istanbul
const c = (id, origin) => ({ id, origin });
const ok = (r) => assert.ok(r.send || REASON_CODES.includes(r.reasonCode), JSON.stringify(r));

let r = await decide({ user: nu, candidate: c('r1', 'requested'), now: noon, config: cfg });
assert.equal(r.send, true);
r = await decide({ user: nu, candidate: c('r1', 'requested'), now: noon, config: cfg });
assert.deepEqual(r, { send: false, reasonCode: 'already_delivered' });
r = await decide({ user: nu, candidate: c('i0', 'inferred'), now: noon, config: cfg });
assert.equal(r.reasonCode, 'new_user_grace'); ok(r);
r = await decide({ user: old, candidate: c('i1', 'inferred'), now: new Date('2026-10-23T19:30:00Z'), config: cfg }); // 22:30 local
assert.equal(r.reasonCode, 'quiet_hours');
assert.equal((await decide({ user: old, candidate: c('i2', 'inferred'), now: noon, config: cfg })).send, true);
assert.equal((await decide({ user: old, candidate: c('i3', 'inferred'), now: noon, config: cfg })).send, true);
r = await decide({ user: old, candidate: c('i4', 'inferred'), now: noon, config: cfg });
assert.equal(r.reasonCode, 'daily_cap_reached');
assert.equal((await decide({ user: old, candidate: c('rem', 'reminder'), now: noon, config: cfg })).send, true); // reminder ignores cap
assert.equal((await decide({ user: old, candidate: c('i5', 'inferred'), now: new Date('2026-10-24T09:00:00Z'), config: cfg })).send, true); // next day

// concurrency: 4 processes x 5 attempts, cap 3 -> exactly 3 sends
process.env.STATE_DIR = fs.mkdtempSync(path.join(os.tmpdir(), 'st-'));
const counts = await Promise.all([1, 2, 3, 4].map(() => new Promise((res) => {
  const ch = fork(process.argv[1], [botPath, 'child']);
  ch.on('message', res);
})));
assert.equal(counts.reduce((a, b) => a + b, 0), 3);
console.log('all checks passed');
